#!/usr/bin/env python3
import sys, os, json, re, stat
from dataclasses import dataclass, field
from typing import List, Optional, Dict, Tuple, Set, Any

VERSION = "deadnix 1.3.1"

# ----------------------------- positions/tokens -----------------------------

@dataclass
class Token:
    kind: str
    value: str
    start: int
    end: int
    line: int
    col: int
    end_line: int
    end_col: int
    children: List[List['Token']] = field(default_factory=list)

    def is_ident(self):
        return self.kind == 'IDENT'

KEYWORDS = {
    'assert','else','if','in','inherit','let','or','rec','then','with'
}

_ident_start_re = re.compile(r'[A-Za-z_]')
_ident_part_re = re.compile(r"[A-Za-z0-9_'\-]")

class Lexer:
    def __init__(self, text: str):
        self.text = text
        self.n = len(text)
        self.line_starts = [0]
        for i,ch in enumerate(text):
            if ch == '\n':
                self.line_starts.append(i+1)
        self.skip_lines: Set[int] = set()

    def pos(self, idx: int) -> Tuple[int,int]:
        # line_starts is small enough for linear? use bisect
        import bisect
        line = bisect.bisect_right(self.line_starts, idx)
        col = idx - self.line_starts[line-1] + 1
        return line, col

    def tok(self, kind, value, start, end, children=None):
        l,c = self.pos(start)
        el,ec = self.pos(end) if end <= self.n else self.pos(self.n)
        return Token(kind, value, start, end, l, c, el, ec, children or [])

    def lex(self) -> List[Token]:
        toks, _ = self.lex_code(0, None)
        return toks

    def skip_ws_comments(self, i: int) -> int:
        s = self.text; n = self.n
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch == '#':
                start = i
                j = s.find('\n', i)
                if j == -1: j = n
                comment = s[i:j]
                if 'deadnix: skip' in comment:
                    line,_ = self.pos(start)
                    self.skip_lines.add(line+1)
                i = j
                continue
            if ch == '/' and i+1 < n and s[i+1] == '*':
                start = i
                j = i+2
                depth = 1
                while j < n and depth:
                    if s.startswith('/*', j):
                        depth += 1; j += 2
                    elif s.startswith('*/', j):
                        depth -= 1; j += 2
                    else:
                        j += 1
                comment = s[start:j]
                if 'deadnix: skip' in comment:
                    line,_ = self.pos(start)
                    self.skip_lines.add(line+1)
                i = j
                continue
            break
        return i

    def lex_code(self, i: int, stop: Optional[str]) -> Tuple[List[Token], int]:
        toks: List[Token] = []
        s = self.text; n = self.n
        while i < n:
            i = self.skip_ws_comments(i)
            if i >= n: break
            if stop and s[i] == stop:
                return toks, i
            ch = s[i]
            # braces: recurse to keep interpolation matching sane, but retain tokens
            if ch == '{':
                start = i
                toks.append(self.tok('PUNCT','{',i,i+1)); i += 1
                inner, i = self.lex_code(i, '}')
                toks.extend(inner)
                if i < n and s[i] == '}':
                    toks.append(self.tok('PUNCT','}',i,i+1)); i += 1
                continue
            if ch == '(':
                toks.append(self.tok('PUNCT','(',i,i+1)); i += 1; continue
            if ch == ')':
                toks.append(self.tok('PUNCT',')',i,i+1)); i += 1; continue
            if ch == '[':
                toks.append(self.tok('PUNCT','[',i,i+1)); i += 1; continue
            if ch == ']':
                toks.append(self.tok('PUNCT',']',i,i+1)); i += 1; continue
            if ch == '}' and not stop:
                toks.append(self.tok('PUNCT','}',i,i+1)); i += 1; continue
            # dynamic antiquotation in code (attr paths)
            if ch == '$' and i+1 < n and s[i+1] == '{':
                toks.append(self.tok('PUNCT','${',i,i+2)); i += 2
                inner, i = self.lex_code(i, '}')
                toks.extend(inner)
                if i < n and s[i] == '}':
                    toks.append(self.tok('PUNCT','}',i,i+1)); i += 1
                continue
            # strings
            if ch == '"':
                tok, i = self.scan_double_string(i)
                toks.append(tok); continue
            if ch == "'" and i+1 < n and s[i+1] == "'":
                tok, i = self.scan_indented_string(i)
                toks.append(tok); continue
            # paths/search paths/uris
            if self.starts_uri(i):
                j = i
                while j < n and not s[j].isspace() and s[j] not in '(){}[];,':
                    j += 1
                toks.append(self.tok('ATOM', s[i:j], i, j)); i = j; continue
            if self.starts_path(i):
                tok, i = self.scan_path(i)
                toks.append(tok); continue
            if ch == '<':
                # path literal <nixpkgs>, unless <= or <| operator
                if i+1 < n and s[i+1] in ['=','|']:
                    toks.append(self.tok('OP', s[i:i+2], i, i+2)); i += 2
                else:
                    j = i+1
                    children=[]
                    while j < n and s[j] != '>':
                        if s[j] == '$' and j+1 < n and s[j+1] == '{':
                            child, k = self.lex_code(j+2, '}')
                            children.append(child)
                            j = k+1 if k < n and s[k] == '}' else k
                        else:
                            j += 1
                    if j < n: j += 1
                    toks.append(self.tok('PATH', s[i:j], i, j, children)); i = j
                continue
            # identifiers / keywords
            if _ident_start_re.match(ch):
                j = i+1
                while j < n and _ident_part_re.match(s[j]):
                    # do not absorb the arrow operator
                    if s[j] == '-' and j+1 < n and s[j+1] == '>':
                        break
                    j += 1
                val = s[i:j]
                kind = 'KW' if val in KEYWORDS else 'IDENT'
                toks.append(self.tok(kind, val, i, j)); i = j; continue
            # numbers
            if ch.isdigit():
                j = i+1
                while j < n and (s[j].isalnum() or s[j] in '._'):
                    j += 1
                toks.append(self.tok('ATOM', s[i:j], i, j)); i = j; continue
            # ellipsis and multi ops
            for op in ['...', '==','!=','<=','>=','&&','||','->','++','//','|>','<|']:
                if s.startswith(op, i):
                    toks.append(self.tok('PUNCT' if op == '...' else 'OP', op, i, i+len(op)))
                    i += len(op); break
            else:
                if ch in '@:;,.=?+-*/!':
                    toks.append(self.tok('PUNCT' if ch in '@:;,.=?' else 'OP', ch, i, i+1)); i += 1
                else:
                    toks.append(self.tok('ATOM', ch, i, i+1)); i += 1
                continue
            continue
        return toks, i

    def scan_double_string(self, i: int) -> Tuple[Token,int]:
        s = self.text; n = self.n; start = i; i += 1; children=[]
        while i < n:
            if s[i] == '\\':
                i += 2; continue
            if s[i] == '$' and i+1 < n and s[i+1] == '{':
                child, k = self.lex_code(i+2, '}')
                children.append(child)
                i = k+1 if k < n and s[k] == '}' else k
                continue
            if s[i] == '"':
                i += 1; break
            i += 1
        return self.tok('STRING', s[start:i], start, i, children), i

    def scan_indented_string(self, i: int) -> Tuple[Token,int]:
        s = self.text; n = self.n; start = i; i += 2; children=[]
        while i < n:
            # In Nix indented strings, ''${ escapes ${}; keep rough behavior.
            if s.startswith("'''", i):
                i += 3; continue
            if s.startswith("''", i):
                i += 2; break
            if s[i] == '$' and i+1 < n and s[i+1] == '{':
                # escaped if immediately preceded by two single quotes in source; approximate
                if i >= 2 and s[i-2:i] == "''":
                    i += 2; continue
                child, k = self.lex_code(i+2, '}')
                children.append(child)
                i = k+1 if k < n and s[k] == '}' else k
                continue
            i += 1
        return self.tok('STRING', s[start:i], start, i, children), i

    def starts_uri(self, i:int)->bool:
        m = re.match(r'[A-Za-z][A-Za-z0-9+.-]*://', self.text[i:])
        return bool(m)

    def starts_path(self, i:int)->bool:
        s=self.text; n=self.n
        if s.startswith('./', i) or s.startswith('../', i) or s.startswith('~/', i): return True
        # absolute path, but do not treat // as path/comment and do not start division after an identifier/number
        if s[i] == '/' and not (i+1<n and s[i+1] in '/*'):
            if i == 0 or self.text[i-1].isspace() or self.text[i-1] in '([{:;,=':
                return True
        return False

    def scan_path(self, i:int)->Tuple[Token,int]:
        s=self.text; n=self.n; start=i; children=[]
        while i<n:
            if s[i].isspace() or s[i] in '(){}[];,':
                break
            if s[i] == '$' and i+1<n and s[i+1]=='{':
                child,k = self.lex_code(i+2,'}')
                children.append(child)
                i = k+1 if k<n and s[k]=='}' else k
                continue
            # stop at operators that cannot be path chars at segment boundary
            i += 1
        return self.tok('PATH', s[start:i], start, i, children), i

# ----------------------------- analysis model ------------------------------

@dataclass(eq=False)
class Declaration:
    id: int
    name: str
    kind: str  # let, lambda_arg, lambda_pattern, silent
    token: Token
    scope: 'Scope'
    is_alias: bool = False
    skipped: bool = False       # pragma skip
    opt_disabled: bool = False  # option says do not check; force used but still analyze nested
    silent: bool = False
    deps: Set['Declaration'] = field(default_factory=set)
    root_refs: int = 0
    force_used: bool = False
    used: bool = False
    unused: bool = False
    # edit metadata
    edit_kind: str = ''
    edit_start: int = 0
    edit_end: int = 0
    parent_meta: Any = None

    def __hash__(self):
        return self.id

@dataclass
class Scope:
    kind: str
    parent: Optional['Scope']
    suppressed: bool = False
    declarations: List[Declaration] = field(default_factory=list)
    by_name: Dict[str,List[Declaration]] = field(default_factory=dict)
    children: List['Scope'] = field(default_factory=list)

class Options:
    def __init__(self):
        self.no_lambda_arg=False
        self.no_lambda_pattern_names=False
        self.no_underscore=False
        self.warn_used_underscore=False
        self.quiet=False
        self.edit=False
        self.hidden=False
        self.fail=False
        self.output_format='human-readable'
        self.excludes=[]

@dataclass
class Source:
    kind: str  # root or decl
    obj: Any

@dataclass
class Finding:
    file: str
    line: int = 0
    column: int = 0
    endColumn: int = 0
    message: str = ''
    start: int = 0
    end: int = 0
    kind: str = ''
    decl: Optional[Declaration] = None

class Analyzer:
    def __init__(self, text: str, options: Options, skip_lines: Set[int]):
        self.text=text
        self.options=options
        self.skip_lines=skip_lines
        self.next_id=1
        self.scopes: List[Scope]=[]
        self.findings: List[Finding]=[]
        self.edit_decls: List[Declaration]=[]

    def new_scope(self, kind, parent, suppressed=False):
        sc=Scope(kind,parent,suppressed)
        if parent: parent.children.append(sc)
        self.scopes.append(sc)
        return sc

    def add_decl(self, scope: Scope, name: str, kind: str, tok: Token, is_alias=False,
                 skipped=False, opt_disabled=False, silent=False, edit_kind='', edit_start=None, edit_end=None, parent_meta=None):
        d=Declaration(self.next_id,name,kind,tok,scope,is_alias,skipped,opt_disabled,silent)
        self.next_id += 1
        d.force_used = skipped or opt_disabled or silent
        d.edit_kind = edit_kind
        d.edit_start = tok.start if edit_start is None else edit_start
        d.edit_end = tok.end if edit_end is None else edit_end
        d.parent_meta = parent_meta
        scope.declarations.append(d)
        scope.by_name.setdefault(name,[]).append(d)
        if not silent:
            self.edit_decls.append(d)
        return d

    def env_with(self, env: List[Scope], sc: Scope):
        return env + [sc]

    def resolve(self, name: str, env: List[Scope]) -> Tuple[Optional[Scope],List[Declaration]]:
        for sc in reversed(env):
            if name in sc.by_name:
                return sc, sc.by_name[name]
        return None, []

    def record_ref(self, name: str, env: List[Scope], sources: Dict[int,Source]):
        sc, decls = self.resolve(name, env)
        if not sc or not decls:
            return
        src = sources.get(id(sc))
        if not src:
            return
        for d in decls:
            if d.silent:
                continue
            if src.kind == 'decl':
                sd: Declaration = src.obj
                if sd is d:
                    continue
                sd.deps.add(d)
            else:
                d.root_refs += 1

    # ---------------- token utilities ----------------
    def val(self,toks,i): return toks[i].value if 0 <= i < len(toks) else None
    def is_kw(self,tok,val): return tok.kind=='KW' and tok.value==val

    def matching_index(self, toks: List[Token], i: int) -> int:
        if i>=len(toks): return i
        openv=toks[i].value
        close={ '{':'}', '${':'}', '(':')', '[':']'}.get(openv)
        if not close: return i
        depth=0
        for j in range(i,len(toks)):
            v=toks[j].value
            if v==openv or (openv in ['{','${'] and v in ['{','${']):
                # For brace-like constructs, both { and ${ increase brace depth.
                if close=='}': depth += 1
                elif v==openv: depth += 1
            elif v==close:
                depth -= 1
                if depth==0: return j
        return len(toks)-1

    def find_top(self, toks, start, end, value):
        depth=0
        for i in range(start,end):
            v=toks[i].value
            if v in ['{','${','(','[']:
                depth += 1
            elif v in ['}',')',']']:
                depth = max(0, depth-1)
            elif depth==0 and v==value:
                return i
        return -1

    def find_lambda_pattern(self, toks, i, end):
        # returns (kind, alias_tok, lbrace, rbrace, colon)
        if i>=end: return None
        if toks[i].value == '{':
            r = self.matching_index(toks,i)
            if r < end:
                if r+1 < end and toks[r+1].value == ':':
                    return ('plain', None, i, r, r+1)
                if r+3 < end and toks[r+1].value == '@' and toks[r+2].kind=='IDENT' and toks[r+3].value==':':
                    return ('suffix', toks[r+2], i, r, r+3)
        if toks[i].kind=='IDENT' and i+2<end and toks[i+1].value=='@' and toks[i+2].value=='{':
            r = self.matching_index(toks,i+2)
            if r+1 < end and toks[r+1].value==':':
                return ('prefix', toks[i], i+2, r, r+1)
        return None

    # ---------------- main analyzer scanner ----------------
    def analyze(self, toks: List[Token]) -> List[Finding]:
        root = self.new_scope('root', None, False)
        sources={id(root): Source('root', root)}
        self.analyze_range(toks, 0, len(toks), [root], sources, False)
        self.solve_all()
        return self.findings

    def analyze_children(self, token: Token, env, sources, suppress):
        for child in token.children:
            child_root = self.new_scope('interp', env[-1] if env else None, suppress)
            # Do not introduce declarations; just analyze child tokens in same env. The dummy
            # scope is not part of env because interpolation has no lexical bindings.
            self.analyze_range(child, 0, len(child), env, sources, suppress)

    def analyze_range(self, toks: List[Token], start: int, end: int, env: List[Scope], sources: Dict[int,Source], suppress: bool):
        i=start
        while i<end:
            tok=toks[i]
            # Let expression
            if self.is_kw(tok,'let'):
                ni = self.parse_let(toks,i,end,env,sources,suppress)
                if ni <= i: i += 1
                else: i = ni
                continue
            # Lambda pattern
            pat = self.find_lambda_pattern(toks,i,end)
            if pat:
                ni = self.parse_pattern_lambda(toks,i,end,env,sources,suppress,pat)
                i = max(ni, i+1)
                continue
            # Simple lambda: IDENT ':'
            if tok.kind=='IDENT' and i+1<end and toks[i+1].value==':':
                ni = self.parse_simple_lambda(toks,i,end,env,sources,suppress)
                i = max(ni, i+1)
                continue
            # rec attrset
            if self.is_kw(tok,'rec') and i+1<end and toks[i+1].value=='{':
                ni = self.parse_attrset(toks,i+1,end,env,sources,suppress,rec=True)
                i = max(ni, i+1)
                continue
            # attrset
            if tok.value == '{':
                ni = self.parse_attrset(toks,i,end,env,sources,suppress,rec=False)
                i = max(ni, i+1)
                continue
            # parentheses/lists: recurse inside
            if tok.value in ['(', '[']:
                r = self.matching_index(toks,i)
                if r>i:
                    self.analyze_range(toks,i+1,r,env,sources,suppress)
                    i = r+1; continue
            # dynamic antiquotation in code
            if tok.value == '${':
                r = self.matching_index(toks,i)
                if r>i:
                    self.analyze_range(toks,i+1,r,env,sources,suppress)
                    i = r+1; continue
            # selection: skip attr components after dot
            if tok.value == '.':
                i = self.skip_selector(toks,i,end,env,sources,suppress)
                continue
            if tok.kind in ['STRING','PATH']:
                self.analyze_children(tok,env,sources,suppress)
                i += 1; continue
            if tok.kind=='IDENT':
                self.record_ref(tok.value,env,sources)
            i += 1

    def skip_selector(self,toks,i,end,env,sources,suppress):
        # consume . attr (. attr)*; analyze dynamic selectors and string interpolations
        while i<end and toks[i].value=='.':
            i += 1
            if i>=end: break
            tok=toks[i]
            if tok.value=='${':
                r=self.matching_index(toks,i)
                if r>i:
                    self.analyze_range(toks,i+1,r,env,sources,suppress)
                    i=r+1
                else: i+=1
            elif tok.kind in ['IDENT','KW','ATOM'] or tok.value=='...' or tok.kind=='STRING':
                if tok.kind=='STRING': self.analyze_children(tok,env,sources,suppress)
                i += 1
            else:
                break
        return i

    # ---------------- declarations/scopes parsers ----------------
    def parse_simple_lambda(self,toks,i,end,env,sources,suppress):
        name_tok=toks[i]
        sc_suppress = suppress or (name_tok.line in self.skip_lines)
        sc = self.new_scope('lambda', env[-1] if env else None, sc_suppress)
        opt_disabled = self.options.no_lambda_arg or name_tok.value.startswith('_')
        if self.options.no_underscore and name_tok.value.startswith('_'):
            opt_disabled=True
        skipped = name_tok.line in self.skip_lines
        self.add_decl(sc,name_tok.value,'lambda_arg',name_tok,skipped=skipped,opt_disabled=opt_disabled,
                      edit_kind='lambda_arg')
        new_env=env+[sc]
        new_sources=dict(sources); new_sources[id(sc)] = Source('root',sc)
        self.analyze_range(toks,i+2,end,new_env,new_sources,sc_suppress)
        return end

    def parse_pattern_lambda(self,toks,i,end,env,sources,suppress,pat):
        kind, alias_tok, lbrace, rbrace, colon = pat
        start_tok = toks[i]
        sc_suppress = suppress or (start_tok.line in self.skip_lines) or (alias_tok.line in self.skip_lines if alias_tok else False)
        sc = self.new_scope('lambda_pattern', env[-1] if env else None, sc_suppress)
        meta={'type':'pattern','lbrace':toks[lbrace].start,'rbrace':toks[rbrace].end,'items':[], 'alias_prefix':None, 'alias_suffix':None}
        if alias_tok:
            opt_disabled = self.options.no_underscore and alias_tok.value.startswith('_')
            skipped = (alias_tok.line in self.skip_lines) or sc_suppress
            d=self.add_decl(sc,alias_tok.value,'lambda_pattern',alias_tok,is_alias=True,skipped=skipped,opt_disabled=opt_disabled,
                            edit_kind='pattern_alias',parent_meta=meta)
            if kind=='prefix': meta['alias_prefix']=(alias_tok.start, toks[lbrace].start) # remove alias@
            else: meta['alias_suffix']=(toks[rbrace].end, alias_tok.end) # remove @alias
        # parse pattern entries and defaults
        entries = self.pattern_entries(toks,lbrace+1,rbrace)
        for ent in entries:
            name_tok, def_start, def_end, item_start, item_end = ent
            opt_disabled = self.options.no_lambda_pattern_names or (self.options.no_underscore and name_tok.value.startswith('_'))
            skipped = (name_tok.line in self.skip_lines) or sc_suppress
            d=self.add_decl(sc,name_tok.value,'lambda_pattern',name_tok,is_alias=False,skipped=skipped,opt_disabled=opt_disabled,
                            edit_kind='pattern_item',edit_start=item_start,edit_end=item_end,parent_meta=meta)
            meta['items'].append((d,item_start,item_end))
        # analyze defaults after declarations exist
        new_env=env+[sc]
        for idx,ent in enumerate(entries):
            name_tok, def_start, def_end, item_start, item_end = ent
            d = meta['items'][idx][0]
            if def_start is not None and def_start < def_end:
                ns=dict(sources); ns[id(sc)] = Source('decl', d)
                self.analyze_range(toks,def_start,def_end,new_env,ns, sc_suppress or d.skipped)
        # body
        new_sources=dict(sources); new_sources[id(sc)] = Source('root',sc)
        self.analyze_range(toks,colon+1,end,new_env,new_sources,sc_suppress)
        return end

    def pattern_entries(self,toks,start,end):
        entries=[]
        i=start
        item_start=i
        while i<end:
            # skip commas
            while i<end and toks[i].value==',':
                i+=1; item_start=i
            if i>=end: break
            if toks[i].value=='...':
                i+=1
                if i<end and toks[i].value==',': i+=1
                item_start=i; continue
            if toks[i].kind=='IDENT':
                name_tok=toks[i]
                j=i+1
                def_start=None; def_end=None
                # default expression until comma at top-level
                if j<end and toks[j].value=='?':
                    def_start=j+1
                    k=self.find_next_comma(toks,def_start,end)
                    def_end=k
                    j=k
                # item end includes following comma if present for edit convenience
                k=j
                if k<end and toks[k].value==',':
                    item_end=toks[k].end; next_i=k+1
                else:
                    item_end=toks[k-1].end if k>item_start else toks[i].end; next_i=k
                entries.append((name_tok,def_start,def_end,toks[item_start].start,item_end))
                i=next_i; item_start=i; continue
            # Unknown pattern thing: skip to comma
            k=self.find_next_comma(toks,i,end)
            i=k+1 if k<end and toks[k].value==',' else k
            item_start=i
        return entries

    def find_next_comma(self,toks,start,end):
        depth=0
        for j in range(start,end):
            v=toks[j].value
            if v in ['{','${','(','[']: depth+=1
            elif v in ['}',')',']']: depth=max(0,depth-1)
            elif depth==0 and v==',': return j
        return end

    def parse_let(self,toks,i,end,env,sources,suppress):
        sc = self.new_scope('let', env[-1] if env else None, suppress)
        new_env = env+[sc]
        # locate top-level 'in'
        in_idx = self.find_let_in(toks,i+1,end)
        if in_idx<0: in_idx=end
        bindings=[]
        p=i+1
        while p<in_idx:
            if toks[p].value==';': p+=1; continue
            if toks[p].kind=='KW' and toks[p].value=='inherit':
                p = self.collect_inherit(toks,p,in_idx,sc,bindings,is_let=True,suppress=suppress)
            else:
                p = self.collect_attr_binding(toks,p,in_idx,sc,bindings,is_let=True,rec=False,suppress=suppress)
        # Analyze binding RHS after all let declarations were added.
        for b in bindings:
            d=b.get('decl')
            ranges=b.get('ranges',[])
            bsuppress = suppress or b.get('skipped',False)
            if d:
                ns=dict(sources); ns[id(sc)] = Source('decl', d)
            else:
                ns=dict(sources); ns[id(sc)] = Source('root', sc)
            for a,bend in ranges:
                if a is not None and a<bend:
                    self.analyze_range(toks,a,bend,new_env,ns,bsuppress)
        # Analyze body.
        ns=dict(sources); ns[id(sc)] = Source('root', sc)
        self.analyze_range(toks,in_idx+1,end,new_env,ns,suppress)
        return end

    def find_let_in(self,toks,start,end):
        depth=0
        for j in range(start,end):
            v=toks[j].value
            if v in ['{','${','(','[']: depth+=1
            elif v in ['}',')',']']: depth=max(0,depth-1)
            elif depth==0 and toks[j].kind=='KW' and toks[j].value=='in': return j
        return -1

    def collect_inherit(self,toks,p,end,sc,bindings,is_let,suppress, rec=False):
        inherit_tok=toks[p]
        j=p+1
        source_range=None
        if j<end and toks[j].value=='(':
            r=self.matching_index(toks,j)
            source_range=(j+1,r)
            j=r+1
        semi=self.find_top(toks,j,end,';')
        if semi<0: semi=end
        # collect identifier attrs at top-level in j..semi
        attrs=[]
        k=j
        while k<semi:
            if toks[k].kind=='IDENT': attrs.append(toks[k])
            k+=1
        if is_let:
            # One binding per inherited attr; source expression is dependency for source inherit.
            for at in attrs:
                skipped = suppress or (inherit_tok.line in self.skip_lines) or (at.line in self.skip_lines)
                opt_disabled = self.options.no_underscore and at.value.startswith('_')
                d=self.add_decl(sc,at.value,'let',at,skipped=skipped,opt_disabled=opt_disabled,
                                edit_kind='inherit_attr',parent_meta={'inherit_start':inherit_tok.start,'stmt_start':inherit_tok.start,'stmt_end': toks[semi].end if semi<end else (toks[semi-1].end if semi>p else inherit_tok.end), 'attrs': []})
                # Parent meta attrs list is not shared currently; fill later in edit through statement scan.
                ranges=[]
                if source_range: ranges.append(source_range)
                bindings.append({'decl':d,'ranges':ranges,'skipped':skipped})
        else:
            # attrset inherit: no declarations. Source inherit analyzes source expr; plain inherit references lexical vars.
            if source_range:
                bindings.append({'decl':None,'ranges':[source_range],'skipped': suppress or inherit_tok.line in self.skip_lines})
            else:
                # Store explicit attr refs as pseudo ranges by recording immediately in caller? Easier: binding has attr_refs.
                bindings.append({'decl':None,'ranges':[],'attr_refs':attrs,'skipped': suppress or inherit_tok.line in self.skip_lines})
        return semi+1 if semi<end else semi

    def collect_attr_binding(self,toks,p,end,sc,bindings,is_let,suppress,rec=False):
        eq=self.find_top(toks,p,end,'=')
        if eq<0:
            return end
        semi=self.find_top(toks,eq+1,end,';')
        if semi<0: semi=end
        first_tok=None
        dynamic_ranges=[]
        # Parse attrpath p..eq. First static identifier gives let/rec declaration.
        k=p; first_component=True
        while k<eq:
            tok=toks[k]
            if tok.value=='.':
                k+=1; first_component=False; continue
            if tok.value=='${':
                r=self.matching_index(toks,k)
                dynamic_ranges.append((k+1,r))
                k=r+1; first_component=False; continue
            if tok.kind=='STRING':
                if tok.children:
                    # Analyze string interpolation children via token child ranges later by direct child token range sentinel.
                    # For simplicity, store token itself by negative marker handled below.
                    pass
                # string attr component, not a declaration
                first_component=False; k+=1; continue
            if tok.kind=='IDENT' or tok.kind=='KW':
                if first_component and tok.kind=='IDENT': first_tok=tok
                first_component=False; k+=1; continue
            k+=1
        # value range plus dynamic attr component ranges. String interpolation children in attr names are analyzed by scanning p..eq selectively below.
        stmt_end = toks[semi].end if semi<end else (toks[semi-1].end if semi>p else toks[eq].end)
        skipped = suppress or (toks[p].line in self.skip_lines) or (first_tok.line in self.skip_lines if first_tok else False)
        ranges=[]
        ranges.extend(dynamic_ranges)
        # Attr name string/path interpolation children: analyze by adding a special token range using a tiny child list in-place during analysis below.
        # We will simply analyze token children now with sources later impossible; instead add tokens to binding.
        child_tokens=[]
        for k in range(p,eq):
            if toks[k].kind in ['STRING','PATH'] and toks[k].children:
                child_tokens.extend(toks[k].children)
        ranges.append((eq+1, semi))
        if is_let and first_tok is not None:
            opt_disabled = self.options.no_underscore and first_tok.value.startswith('_')
            d=self.add_decl(sc,first_tok.value,'let',first_tok,skipped=skipped,opt_disabled=opt_disabled,
                            edit_kind='let_binding',edit_start=toks[p].start,edit_end=stmt_end)
            bindings.append({'decl':d,'ranges':ranges,'child_tokens':child_tokens,'skipped':skipped})
        elif rec and first_tok is not None:
            # silent rec attr declaration
            self.add_decl(sc,first_tok.value,'silent',first_tok,skipped=False,opt_disabled=True,silent=True)
            bindings.append({'decl':None,'ranges':ranges,'child_tokens':child_tokens,'skipped':skipped})
        else:
            bindings.append({'decl':None,'ranges':ranges,'child_tokens':child_tokens,'skipped':skipped})
        return semi+1 if semi<end else semi

    def parse_attrset(self,toks,i,end,env,sources,suppress,rec=False):
        r=self.matching_index(toks,i)
        if r<=i: return i+1
        if rec:
            sc=self.new_scope('rec_attrset', env[-1] if env else None, suppress)
            new_env=env+[sc]
        else:
            sc=None; new_env=env
        bindings=[]
        p=i+1
        # first pass for rec: collect silent declarations from attr bindings/inherits
        while p<r:
            if toks[p].value==';': p+=1; continue
            if toks[p].kind=='KW' and toks[p].value=='inherit':
                if rec:
                    # collect silent attrs, but plain inherit RHS should resolve in parent; source inherit source later.
                    j=p+1
                    if j<r and toks[j].value=='(':
                        rr=self.matching_index(toks,j); j=rr+1
                    semi=self.find_top(toks,j,r,';')
                    if semi<0: semi=r
                    for k in range(j,semi):
                        if toks[k].kind=='IDENT':
                            self.add_decl(sc,toks[k].value,'silent',toks[k],opt_disabled=True,silent=True)
                    p=semi+1 if semi<r else semi
                else:
                    p=self.collect_inherit(toks,p,r,sc if sc else (env[-1] if env else None),bindings,is_let=False,suppress=suppress)
            else:
                if rec:
                    p=self.collect_attr_binding(toks,p,r,sc,bindings,is_let=False,rec=True,suppress=suppress)
                else:
                    p=self.collect_attr_binding(toks,p,r,env[-1] if env else None,bindings,is_let=False,rec=False,suppress=suppress)
        # second pass for rec inherit and all nonrec was partly collected. For rec we need also collect inherit bindings ranges.
        if rec:
            bindings=[]; p=i+1
            while p<r:
                if toks[p].value==';': p+=1; continue
                if toks[p].kind=='KW' and toks[p].value=='inherit':
                    # For rec attrset plain inherit references parent env, source inherit analyzes source in new env.
                    inherit_tok=toks[p]
                    j=p+1; source_range=None
                    if j<r and toks[j].value=='(':
                        rr=self.matching_index(toks,j); source_range=(j+1,rr); j=rr+1
                    semi=self.find_top(toks,j,r,';')
                    if semi<0: semi=r
                    attrs=[toks[k] for k in range(j,semi) if toks[k].kind=='IDENT']
                    if source_range:
                        bindings.append({'decl':None,'ranges':[source_range],'attr_refs':[],'skipped':suppress or inherit_tok.line in self.skip_lines})
                    else:
                        bindings.append({'decl':None,'ranges':[],'attr_refs':attrs,'plain_rec_inherit':True,'skipped':suppress or inherit_tok.line in self.skip_lines})
                    p=semi+1 if semi<r else semi
                else:
                    p=self.collect_attr_binding(toks,p,r,sc,bindings,is_let=False,rec=True,suppress=suppress)
        # Analyze bindings. Nonrec bindings collected with no declarations. Rec env includes silent decls.
        for b in bindings:
            bsuppress=suppress or b.get('skipped',False)
            ns=dict(sources)
            if rec and sc:
                ns[id(sc)] = Source('root', sc)
            # Plain attrset inherit refs: record lexical refs. For rec plain inherit, resolve in parent env (exclude rec silent self).
            if b.get('attr_refs'):
                ref_env = env if b.get('plain_rec_inherit') else new_env
                for at in b['attr_refs']:
                    self.record_ref(at.value, ref_env, sources)
            for child in b.get('child_tokens',[]):
                self.analyze_range(child,0,len(child),new_env,ns,bsuppress)
            for a,bend in b.get('ranges',[]):
                if a is not None and a<bend:
                    self.analyze_range(toks,a,bend,new_env,ns,bsuppress)
        return r+1

    def solve_all(self):
        # solve children/scopes in creation order; findings sorted globally later
        for sc in self.scopes:
            self.solve_scope(sc)
        self.findings.sort(key=lambda f:(f.line,f.column,f.endColumn,f.message))

    def solve_scope(self, sc: Scope):
        decls=[d for d in sc.declarations if not d.silent]
        if not decls: return
        indeg={d:0 for d in decls}
        outgoing={d:set([x for x in d.deps if x in indeg and x is not d]) for d in decls}
        for d in decls:
            indeg[d] += d.root_refs
            if d.force_used: indeg[d] += 1
        for d in decls:
            for dep in outgoing[d]:
                indeg[dep] += 1
        removed=set()
        queue=[d for d in decls if indeg[d]==0]
        while queue:
            d=queue.pop(0)
            if d in removed: continue
            removed.add(d)
            for dep in outgoing[d]:
                indeg[dep] -= 1
                if indeg[dep]==0 and dep not in removed:
                    queue.append(dep)
        for d in decls:
            d.unused = d in removed
            d.used = not d.unused
            self.maybe_report(d, sc)

    def maybe_report(self,d:Declaration,sc:Scope):
        if sc.suppressed or d.skipped or d.silent:
            return
        # option-disabled declarations are never reported
        if d.opt_disabled:
            return
        msg=None
        if d.kind=='let':
            if d.name.startswith('_') and self.options.warn_used_underscore and d.used:
                msg=f"Used let binding: {d.name}"
            elif d.unused:
                msg=f"Unused let binding: {d.name}"
        elif d.kind=='lambda_arg':
            if d.unused:
                msg=f"Unused lambda argument: {d.name}"
        elif d.kind=='lambda_pattern':
            if d.name.startswith('_') and self.options.warn_used_underscore and d.used:
                msg=f"Used lambda pattern: {d.name}"
            elif d.unused:
                msg=f"Unused lambda pattern: {d.name}"
        if msg:
            self.findings.append(Finding('',d.token.line,d.token.col,d.token.end_col,msg,d.token.start,d.token.end,d.kind,d))

# ----------------------------- edit support --------------------------------

def apply_edits(text: str, findings: List[Finding], analyzer: Analyzer) -> str:
    # Original edit mode is intentionally simple and occasionally panics. This
    # implementation performs conservative textual rewrites based on declaration metadata.
    remove_ranges=[]
    replace_ranges=[]
    # Group inherit attrs by statement for nicer list rewriting is difficult because
    # per-decl metadata is minimal; do a generic token-span removal for attrs and clean up.
    for f in findings:
        d=f.decl
        if not d or not d.unused:
            continue
        if d.kind=='lambda_arg':
            if not d.name.startswith('_'):
                replace_ranges.append((d.token.start,d.token.end,'_'+d.name))
        elif d.kind=='lambda_pattern':
            if d.edit_kind=='pattern_alias':
                meta=d.parent_meta or {}
                rng = meta.get('alias_prefix') or meta.get('alias_suffix')
                if rng: remove_ranges.append(rng)
                else: remove_ranges.append((d.token.start,d.token.end))
            elif d.edit_kind=='pattern_item':
                remove_ranges.append((d.edit_start,d.edit_end))
        elif d.kind=='let':
            if d.edit_kind=='inherit_attr':
                # remove just the attr token; later cleanup empty inherit statements
                remove_ranges.append((d.token.start,d.token.end))
            else:
                # remove whole statement, including following newline when line-local
                a,b=d.edit_start,d.edit_end
                # Include indentation at start of line if the statement occupies its own line.
                line_start=text.rfind('\n',0,a)+1
                prefix=text[line_start:a]
                if prefix.strip()=='' :
                    a=line_start
                    if b < len(text) and text[b:b+1]=='\n': b+=1
                remove_ranges.append((a,b))
    # Apply removals/replacements from right to left.
    edits=[]
    for a,b in remove_ranges:
        if a<b: edits.append((a,b,''))
    edits.extend(replace_ranges)
    edits.sort(key=lambda x:(x[0],x[1]), reverse=True)
    out=text
    for a,b,r in edits:
        if 0 <= a <= b <= len(out):
            out=out[:a]+r+out[b:]
    out=cleanup_after_edit(out)
    return out

def cleanup_after_edit(s: str) -> str:
    # Remove empty inherit statements and tidy commas in patterns. Keep this deliberately
    # conservative.
    # Empty inherit with optional source.
    s=re.sub(r'(?m)^[ \t]*inherit(?:\s*\([^;]*\))?\s*;\n?','',s)
    s=re.sub(r'inherit(?:\s*\([^;]*\))?\s*;','',s)
    # Multiple commas and leading commas in patterns.
    s=re.sub(r'\{\s*,\s*','{ ',s)
    s=re.sub(r',\s*,+',',',s)
    s=re.sub(r',\s*\}', ' }', s)
    s=re.sub(r'\{\s*\}', '{ }', s)
    # Clean inherit lists with extra spaces before semicolon.
    s=re.sub(r'inherit(\s*\([^)]*\))?\s+;', r'inherit\1;', s)
    return s

# ----------------------------- output --------------------------------------

def json_for_file(path: str, findings: List[Finding], errors: List[str]) -> Optional[str]:
    if not findings and not errors:
        return None
    results=[]
    for e in errors:
        results.append({'message':e})
    for f in findings:
        results.append({'column':f.column,'endColumn':f.endColumn,'line':f.line,'message':f.message})
    return json.dumps({'file':path,'results':results}, separators=(',',':'))

ANSI_RESET='\033[0m'; ANSI_YELLOW='\033[33m'

def color(s,c,enabled):
    if not enabled: return s
    return c+s+ANSI_RESET

def human_report(path: str, text: str, findings: List[Finding], errors: List[str], color_enabled=True, quiet=False):
    if errors:
        for e in errors:
            print(f"Error parsing file {path}: {e}" if 'os error' not in e else f"Error stating file {path}: {e}", file=sys.stderr)
        return
    if not findings or quiet:
        return
    print(f"{color('Warning:', ANSI_YELLOW, color_enabled)} Unused declarations were found.")
    lines=text.splitlines()
    if not lines: lines=['']
    first=findings[0]
    print(f"    ╭─[{path}:{first.line}:{first.column}]")
    byline: Dict[int,List[Finding]]={}
    for f in findings: byline.setdefault(f.line,[]).append(f)
    width=max(1,len(str(max(byline.keys()))))
    for ln in sorted(byline):
        src=lines[ln-1] if 1 <= ln <= len(lines) else ''
        print(f" {ln:>{width}} │{src}")
        # Print labels in reverse column order like ariadne often does for same line.
        for f in sorted(byline[ln], key=lambda x:x.column, reverse=True):
            col=max(1,f.column)
            span=max(1,f.endColumn-f.column)
            prefix=f" {'':>{width}} │" + ' '*(col-1)
            if span==1:
                mark='╰'
            else:
                mark='╰'+'─'*(max(0,span-2))
            print(prefix+mark+" "+f.message)

