HELP_TEMPLATE = """Find dead code in .nix files

Usage: {prog} [OPTIONS] [FILE_PATHS]...

Arguments:
  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]

Options:
  -l, --no-lambda-arg                  Don't check lambda parameter arguments
  -L, --no-lambda-pattern-names        Don't check lambda attrset pattern names (don't break nixpkgs callPackage)
  -_, --no-underscore                  Don't check any bindings that start with a _
                                       (Lambda arguments starting with _ are not checked anyway.)
  -W, --warn-used-underscore           Warn if bindings are referenced that start with '_'
  -q, --quiet                          Don't print dead code report
  -e, --edit                           Remove unused code and write to source file
  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files
      --help                           
  -f, --fail                           Exit with 1 if unused code has been found
  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]
      --exclude <EXCLUDES>...          Files to exclude from analysis
  -V, --version                        Print version
"""

def parse_args(argv: List[str]) -> Tuple[Options,List[str],Optional[int]]:
    opt=Options(); paths=[]; i=0; after_dd=False
    prog=os.path.basename(sys.argv[0])
    while i < len(argv):
        a=argv[i]
        if after_dd:
            paths.append(a); i+=1; continue
        if a=='--':
            after_dd=True; i+=1; continue
        if a=='--help':
            print(HELP_TEMPLATE.format(prog=prog), end=''); return opt, paths, 0
        if a in ['-V','--version']:
            print(VERSION); return opt, paths, 0
        if a in ['-l','--no-lambda-arg']:
            opt.no_lambda_arg=True; i+=1; continue
        if a in ['-L','--no-lambda-pattern-names']:
            opt.no_lambda_pattern_names=True; i+=1; continue
        if a in ['-_','--no-underscore']:
            opt.no_underscore=True; i+=1; continue
        if a in ['-W','--warn-used-underscore']:
            opt.warn_used_underscore=True; i+=1; continue
        if a in ['-q','--quiet']:
            opt.quiet=True; i+=1; continue
        if a in ['-e','--edit']:
            opt.edit=True; i+=1; continue
        if a in ['-h','--hidden']:
            opt.hidden=True; i+=1; continue
        if a in ['-f','--fail']:
            opt.fail=True; i+=1; continue
        if a in ['-o','--output-format'] or a.startswith('--output-format=') or (a.startswith('-o') and len(a)>2):
            if a.startswith('--output-format='):
                val=a.split('=',1)[1]
            elif a.startswith('-o') and len(a)>2:
                val=a[2:]
            else:
                if i+1>=len(argv):
                    print("error: a value is required for '--output-format <OUTPUT_FORMAT>'", file=sys.stderr); return opt,paths,2
                val=argv[i+1]; i+=1
            if val not in ['human-readable','json']:
                print(f"error: invalid value '{val}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.", file=sys.stderr)
                return opt,paths,2
            opt.output_format=val; i+=1; continue
        if a=='--exclude' or a.startswith('--exclude='):
            vals=[]
            if a.startswith('--exclude='):
                vals.append(a.split('=',1)[1])
            else:
                i+=1
                while i<len(argv) and argv[i] != '--' and not argv[i].startswith('-'):
                    vals.append(argv[i]); i+=1
                opt.excludes.extend(vals)
                continue
            opt.excludes.extend(vals); i+=1; continue
        # short flag clusters like -eq or -flLq. -_ is a whole flag.
        if a.startswith('-') and len(a)>2 and not a.startswith('--'):
            ok=True
            for ch in a[1:]:
                if ch=='l': opt.no_lambda_arg=True
                elif ch=='L': opt.no_lambda_pattern_names=True
                elif ch=='_': opt.no_underscore=True
                elif ch=='W': opt.warn_used_underscore=True
                elif ch=='q': opt.quiet=True
                elif ch=='e': opt.edit=True
                elif ch=='h': opt.hidden=True
                elif ch=='f': opt.fail=True
                elif ch=='V': print(VERSION); return opt,paths,0
                else: ok=False; break
            if ok:
                i+=1; continue
        if a.startswith('-'):
            print(f"error: unexpected argument '{a}' found\n\n  tip: to pass '{a}' as a value, use '-- {a}'\n\nUsage: {prog} [OPTIONS] [FILE_PATHS]...\n\nFor more information, try '--help'.", file=sys.stderr)
            return opt,paths,2
        paths.append(a); i+=1
    if not paths: paths=['.']
    return opt, paths, None

def is_hidden_path(path: str) -> bool:
    base=os.path.basename(path.rstrip(os.sep))
    return base.startswith('.') and base not in ('','.','..')

def gather_files(paths: List[str], opt: Options) -> Tuple[List[str],List[Tuple[str,str]]]:
    files=[]; errors=[]
    exclude_real=set()
    for e in opt.excludes:
        try: exclude_real.add(os.path.realpath(e))
        except Exception: pass
    for p in paths:
        try:
            st=os.stat(p)
        except OSError as e:
            errors.append((p, str(e)))
            continue
        if stat.S_ISDIR(st.st_mode):
            if not opt.hidden and is_hidden_path(p):
                continue
            for root, dirs, names in os.walk(p):
                if not opt.hidden:
                    dirs[:] = [d for d in dirs if not d.startswith('.')]
                    names = [n for n in names if not n.startswith('.')]
                # os.walk/scandir order is used intentionally (like walkdir without sorting).
                for n in names:
                    if not n.endswith('.nix'):
                        continue
                    full=os.path.join(root,n)
                    if os.path.realpath(full) in exclude_real:
                        continue
                    files.append(full)
        else:
            # explicit files are processed regardless of extension/hidden/excludes
            files.append(p)
    return files, errors

def process_file(path: str, display_path: str, opt: Options) -> Tuple[List[Finding],List[str],str,bool]:
    try:
        with open(path,'r',encoding='utf-8') as f:
            text=f.read()
    except OSError as e:
        return [], [str(e)], '', False
    except UnicodeDecodeError as e:
        return [], [str(e)], '', False
    try:
        lex=Lexer(text); toks=lex.lex()
        # A very small parse-error approximation: empty/comment-only files are errors like rnix.
        errors=[]
        if not toks:
            errors=['unexpected end of file']
            return [], errors, text, False
        analyzer=Analyzer(text,opt,lex.skip_lines)
        findings=analyzer.analyze(toks)
        for f in findings: f.file=display_path
        if opt.edit and findings and not errors:
            new_text=apply_edits(text,findings,analyzer)
            if new_text != text:
                with open(path,'w',encoding='utf-8') as f: f.write(new_text)
        return findings, errors, text, any(f.message.startswith('Unused') or f.message.startswith('Used') for f in findings)
    except Exception as e:
        # Avoid crashing on unusual syntax; report parser-ish error.
        return [], [str(e)], text, False

def display_for(path: str, arg_is_dir_context=True) -> str:
    return path

# ----------------------------- main ----------------------------------------

def main(argv=None):
    if argv is None: argv=sys.argv[1:]
    opt, paths, early = parse_args(argv)
    if early is not None:
        return early
    files, stat_errors = gather_files(paths,opt)
    any_findings=False
    color_enabled = 'NO_COLOR' not in os.environ
    # Stat errors from gather
    if opt.output_format=='json':
        for p,e in stat_errors:
            obj=json_for_file(p,[],[e])
            if obj: print(obj)
    else:
        for p,e in stat_errors:
            print(f"Error stating file {p}: {e}", file=sys.stderr)
    for fpath in files:
        # Preserve the path string as walk produced it. For directory args os.walk on '.' yields './x'.
        disp=fpath
        findings, errors, text, has = process_file(fpath,disp,opt)
        if findings: any_findings=True
        if opt.output_format=='json':
            obj=json_for_file(disp,findings,errors)
            if obj: print(obj)
        else:
            human_report(disp,text,findings,errors,color_enabled,opt.quiet)
    if opt.fail and any_findings:
        return 1
    return 0

if __name__=='__main__':
    sys.exit(main())
